package com.nigson.acceptance.reporting;

import java.time.Instant;
import java.util.Set;
import java.util.UUID;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import com.nigson.acceptance.order.OrderFixture;
import com.nigson.commerce.reporting.*;
import com.nigson.shared.problem.Problem;
import com.nigson.shared.security.ActorAssertion;
import static org.assertj.core.api.Assertions.*;

class ReportPersistenceTest {
    OrderFixture f; ReportService reports; UUID reportParty,refundId; ActorAssertion.Actor analyst; int auditCountBefore;
    @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null&&System.getenv("NIGSON_TEST_ORDER_PAYSTACK")!=null,"reporting-check supplies isolated native Commerce PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_REPORT_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");f=new OrderFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));reportParty=f.prices.finance.party();auditCountBefore=f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE action='COMMERCE_REPORT_READ'",Integer.class);f.jdbc.update("INSERT INTO commerce.staff_role_assignment(id,created_by,updated_by,party_id,role,granted_by) VALUES (?,'test','test',?,'ANALYST',?)",UUID.randomUUID(),reportParty,reportParty);analyst=new ActorAssertion.Actor(reportParty,f.prices.finance.identityIssuer(),f.prices.finance.identitySubject(),null,Set.of("ANALYST"),Set.of(),Instant.now());reports=new ReportService(f.jdbc,new JdbcReportRepository(f.jdbc),f.tx.getTransactionManager(),f.prices.metrics,new com.nigson.commerce.platform.AuditWriter(f.jdbc,java.time.Clock.systemUTC(),f.prices.metrics));}
    @AfterEach void cleanup(){if(f!=null){if(refundId!=null){f.jdbc.update("DELETE FROM commerce.refund_line WHERE refund_id=?",refundId);f.jdbc.update("DELETE FROM commerce.refund WHERE id=?",refundId);}f.jdbc.update("DELETE FROM commerce.staff_role_assignment WHERE party_id=? AND role='ANALYST'",reportParty);f.close();}}
    @Test void utcHalfOpenWindowUsesSuccessfulRefundTotalsAndOrganizationBoundary(){var created=f.checkout("report-paid");f.progress(created,"success");f.payments.inspect(created.order().id(),UUID.randomUUID());var order=created.order();UUID org=f.prices.organization(), other=f.prices.organization();Instant at=Instant.parse("2026-10-18T12:00:00Z");f.jdbc.update("UPDATE commerce.sales_order SET organization_id=?,created_at=?,refunded_total=10.00,payment_status='PARTIALLY_REFUNDED' WHERE id=?",org,java.sql.Timestamp.from(at),order.id());refundId=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.refund(id,created_by,updated_by,order_id,attempt_id,request_key,amount,currency_code,state,reason,requested_by,provider_reference) VALUES (?,'test','test',?,?,?, '10.00','NGN','SUCCEEDED','Synthetic refund fixture',?,?)",refundId,order.id(),created.payment().attemptId(),"report-refund-"+refundId,reportParty,"report-provider-"+refundId);UUID line=f.jdbc.queryForObject("SELECT id FROM commerce.order_line WHERE order_id=?",UUID.class,order.id());f.jdbc.update("INSERT INTO commerce.refund_line(id,created_by,updated_by,refund_id,order_line_id,quantity,amount) VALUES (?,'test','test',?,?,1,10.00)",UUID.randomUUID(),refundId,line);
        var inclusive=new ReportValues.Query(at,at.plusSeconds(1),"NGN",org);var summary=reports.commerce(analyst,inclusive);assertThat(summary.sales().amount()).isEqualTo("18.13");assertThat(summary.orders()).isEqualTo(1);assertThat(summary.customers()).isEqualTo(1);assertThat(summary.products()).hasSize(1);assertThat(summary.products().getFirst().revenue().amount()).isEqualTo("14.68");assertThat(summary.period().from()).isEqualTo(at);assertThat(reports.commerce(analyst,new ReportValues.Query(at.plusSeconds(1),at.plusSeconds(2),"NGN",org)).orders()).isZero();assertThat(reports.commerce(analyst,new ReportValues.Query(at.minusSeconds(1),at,"NGN",org)).orders()).isZero();
        var scoped=new ActorAssertion.Actor(reportParty,analyst.identityIssuer(),analyst.identitySubject(),org,Set.of("ANALYST"),Set.of(),Instant.now());assertThat(reports.commerce(scoped,inclusive).orders()).isEqualTo(1);assertThatThrownBy(()->reports.commerce(scoped,new ReportValues.Query(at,at.plusSeconds(1),"NGN",other))).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->reports.commerce(new ActorAssertion.Actor(reportParty,analyst.identityIssuer(),analyst.identitySubject(),null,Set.of("SALES"),Set.of(),Instant.now()),inclusive)).hasMessage("ACCESS_DENIED");assertThat(f.prices.metrics.get("nigson.reporting.queries").tag("report","commerce").counter().count()).isEqualTo(4);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE action='COMMERCE_REPORT_READ'",Integer.class)-auditCountBefore).isEqualTo(4);
    }
    @Test void rejectsUnboundedPeriodsAndDoesNotReadForeignCurrency(){assertThatThrownBy(()->new ReportValues.Query(Instant.parse("2025-01-01T00:00:00Z"),Instant.parse("2026-01-03T00:00:00Z"),"NGN",null)).hasMessage("VALIDATION_ERROR");assertThatThrownBy(()->reports.commerce(analyst,new ReportValues.Query(Instant.parse("2026-10-18T00:00:00Z"),Instant.parse("2026-10-19T00:00:00Z"),"USD",null))).hasMessage("VALIDATION_ERROR");}
}
